import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';
import 'package:provider/provider.dart';
import '../../../providers/erp_provider.dart';
import 'meeting_details_dialog.dart';

/// Interactive Live Alert Notification System
/// Modal bottom sheet displaying real-time alerts generated by Team Leads & Managers:
/// - New task assignments
/// - Strategy review meeting scheduled
/// - Approaching deadline reminders
/// - Task submissions / delivery confirmations
/// - Actions: Mark alerts as read or clear notifications
class EmployeeNotificationsSheet extends StatefulWidget {
  const EmployeeNotificationsSheet({super.key});

  @override
  State<EmployeeNotificationsSheet> createState() => _EmployeeNotificationsSheetState();
}

class _EmployeeNotificationsSheetState extends State<EmployeeNotificationsSheet> {
  int _selectedFilter = 0; // 0: All, 1: Lead Alerts, 2: Meetings, 3: Deadlines

  @override
  Widget build(BuildContext context) {
    final erp = context.watch<ErpProvider>();

    // Centralized dynamic notifications from ErpProvider
    final notifications = erp.allEmployeeNotifications;

    // Filter list
    final filtered = notifications.where((n) {
      if (_selectedFilter == 1) return n['type'] == 'task' || n['type'] == 'lead' || n['type'] == 'submission';
      if (_selectedFilter == 2) return n['type'] == 'meeting';
      if (_selectedFilter == 3) return n['type'] == 'deadline';
      return true;
    }).toList();

    return Container(
      constraints: BoxConstraints(
        maxHeight: MediaQuery.of(context).size.height * 0.85,
      ),
      decoration: const BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
      ),
      child: Column(
        children: [
          // Drag handle
          Center(
            child: Container(
              margin: const EdgeInsets.only(top: 12, bottom: 8),
              width: 38,
              height: 4.5,
              decoration: BoxDecoration(
                color: const Color(0xFFDEE2E6),
                borderRadius: BorderRadius.circular(3),
              ),
            ),
          ),

          // Header
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 8),
            child: Row(
              children: [
                Container(
                  padding: const EdgeInsets.all(8),
                  decoration: BoxDecoration(
                    color: const Color(0xFF212529),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: const Icon(Icons.notifications_active_rounded, color: Colors.white, size: 18),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(
                    'Live Alerts & Notifications',
                    style: TextStyle(
                      fontFamily: GoogleFonts.instrumentSans().fontFamily,
                      fontSize: 15,
                      fontWeight: FontWeight.w800,
                      color: const Color(0xFF212529),
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
                TextButton(
                  onPressed: () {
                    erp.markAllAlertsAsRead();
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        backgroundColor: const Color(0xFF212529),
                        behavior: SnackBarBehavior.floating,
                        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
                        content: Text(
                          'All alerts marked as read',
                          style: TextStyle(fontFamily: GoogleFonts.instrumentSans().fontFamily),
                        ),
                        duration: const Duration(seconds: 1),
                      ),
                    );
                  },
                  child: Text(
                    'Mark all read',
                    style: TextStyle(
                      fontFamily: GoogleFonts.instrumentSans().fontFamily,
                      fontSize: 12,
                      fontWeight: FontWeight.w700,
                      color: const Color(0xFF0284C7),
                    ),
                  ),
                ),
                IconButton(
                  icon: const Icon(Icons.clear_all_rounded, size: 20, color: Color(0xFF6C757D)),
                  tooltip: 'Clear notifications',
                  onPressed: () {
                    erp.clearAlerts();
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        backgroundColor: const Color(0xFF212529),
                        behavior: SnackBarBehavior.floating,
                        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
                        content: Text(
                          'Cleared notifications feed',
                          style: TextStyle(fontFamily: GoogleFonts.instrumentSans().fontFamily),
                        ),
                        duration: const Duration(seconds: 1),
                      ),
                    );
                  },
                ),
              ],
            ),
          ),

          // Filter Chips
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 4),
            child: Row(
              children: [
                _buildFilterChip(0, 'All Alerts (${notifications.length})'),
                const SizedBox(width: 6),
                _buildFilterChip(1, 'Lead & Manager'),
                const SizedBox(width: 6),
                _buildFilterChip(2, 'Meetings'),
                const SizedBox(width: 6),
                _buildFilterChip(3, 'Deadlines'),
              ],
            ),
          ),
          const SizedBox(height: 8),
          const Divider(height: 1, color: Color(0xFFF1F3F5)),

          // Notifications List
          Expanded(
            child: filtered.isEmpty
                ? Center(
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        const Icon(Icons.done_all_rounded, size: 36, color: Color(0xFFADB5BD)),
                        const SizedBox(height: 8),
                        Text(
                          'All caught up!',
                          style: TextStyle(
                            fontFamily: GoogleFonts.instrumentSans().fontFamily,
                            fontSize: 14,
                            fontWeight: FontWeight.w700,
                            color: const Color(0xFF495057),
                          ),
                        ),
                        Text(
                          'No active alerts in this category.',
                          style: TextStyle(
                            fontFamily: GoogleFonts.instrumentSans().fontFamily,
                            fontSize: 12,
                            color: const Color(0xFFADB5BD),
                          ),
                        ),
                      ],
                    ),
                  )
                : ListView.separated(
                    padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 12),
                    itemCount: filtered.length,
                    separatorBuilder: (context, index) => const SizedBox(height: 8),
                    itemBuilder: (ctx, idx) {
                      final item = filtered[idx];
                      return _buildNotificationCard(ctx, item);
                    },
                  ),
          ),
        ],
      ),
    );
  }

  Widget _buildFilterChip(int index, String label) {
    final isSelected = _selectedFilter == index;
    return InkWell(
      onTap: () => setState(() => _selectedFilter = index),
      borderRadius: BorderRadius.circular(20),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 5),
        decoration: BoxDecoration(
          color: isSelected ? const Color(0xFF212529) : const Color(0xFFF5F6F7),
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: isSelected ? const Color(0xFF212529) : const Color(0xFFE9ECEF),
          ),
        ),
        child: Text(
          label,
          style: TextStyle(
            fontFamily: GoogleFonts.instrumentSans().fontFamily,
            fontSize: 11.5,
            fontWeight: FontWeight.w700,
            color: isSelected ? Colors.white : const Color(0xFF495057),
          ),
        ),
      ),
    );
  }

  Widget _buildNotificationCard(BuildContext context, Map<String, dynamic> item) {
    final isUrgent = item['isUrgent'] == true;
    final isRead = item['isRead'] == true;

    return InkWell(
      onTap: () {
        context.read<ErpProvider>().markAlertAsRead(item['id'] as String);
        if (item['meeting'] != null) {
          Navigator.pop(context);
          showDialog(
            context: context,
            builder: (_) => MeetingDetailsDialog(meeting: item['meeting']),
          );
        }
      },
      borderRadius: BorderRadius.circular(16),
      child: Container(
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          color: isRead ? const Color(0xFFFAFBFB) : Colors.white,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(
            color: isUrgent ? const Color(0xFFFECDD3) : const Color(0xFFE9ECEF),
            width: isUrgent ? 1.4 : 1.0,
          ),
          boxShadow: [
            if (!isRead)
              BoxShadow(
                color: const Color(0xFF212529).withOpacity(0.04),
                blurRadius: 6,
                offset: const Offset(0, 2),
              ),
          ],
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Container(
              padding: const EdgeInsets.all(8),
              decoration: BoxDecoration(
                color: (item['color'] as Color).withOpacity(0.12),
                shape: BoxShape.circle,
              ),
              child: Icon(item['icon'] as IconData, size: 18, color: item['color'] as Color),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Expanded(
                        child: Text(
                          item['title'] as String,
                          style: TextStyle(
                            fontFamily: GoogleFonts.instrumentSans().fontFamily,
                            fontSize: 13,
                            fontWeight: FontWeight.w800,
                            color: const Color(0xFF212529),
                          ),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                      Text(
                        item['time'] as String,
                        style: TextStyle(
                          fontFamily: GoogleFonts.instrumentSans().fontFamily,
                          fontSize: 10.5,
                          fontWeight: FontWeight.w600,
                          color: const Color(0xFF868E96),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 4),
                  Text(
                    item['subtitle'] as String,
                    style: TextStyle(
                      fontFamily: GoogleFonts.instrumentSans().fontFamily,
                      fontSize: 12,
                      color: const Color(0xFF495057),
                      height: 1.35,
                    ),
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}
